GEN = ('yıldız', 'yildiz', 'kart', 'kartım', 'kredi')
NUMW = dict(sıfır=0, bir=1, iki=2, üç=3, dört=4, beş=5, altı=6, yedi=7, sekiz=8, dokuz=9, on=10, yirmi=20, otuz=30,
