    s = words(major) + ' ' + unit
    if minor:
        s += ' ' + words(minor) + ' ' + sub
    return s

def suffix(phrase):
    w = phrase.strip().split(' ')[-1].lower()
    v = 'ı'
    for ch in reversed(w):
        if ch in 'aı':
            v = 'ı'; break
        if ch in 'ei':
            v = 'i'; break
        if ch in 'ou':
            v = 'u'; break
        if ch in 'öü':
            v = 'ü'; break
    c = 't' if w and w[-1] in 'fstkçşhp' else 'd'
    return c + v + 'r'

