ORD = ['', 'birinci', 'ikinci', 'üçüncü', 'dördüncü']
CUR = [('debtTL', 'Türk Lirası', 'TL'), ('debtUSD', 'Dolar', 'USD'), ('debtEUR', 'Euro', 'EUR'), ('debtGBP', 'İngiliz Sterlini', 'GBP')]

def w3(n):
    h, r = divmod(n, 100)
    t, o = divmod(r, 10)
    p = []
    if h:
        p.append('yüz' if h == 1 else ONES[h] + ' yüz')
    if t:
        p.append(TENS[t])
    if o:
        p.append(ONES[o])
    return ' '.join(p)

def words(n):
